/**
 * Синтетический микрофон. Ставить на контекст ДО перехода по ссылке. Уровень: window.__qaMic.level (0.3 — речь/тон,
 * 0.0002 — «тихая комната», 0 — ЦИФРОВОЙ НОЛЬ). Каждый getUserMedia({audio}) получает новый поток от общего усилителя,
 * поэтому повторный запрос клиента при восстановлении работает. Счётчик появлений карточки — window.__qaMic.cardShown.
 * Скрипт строкой JS (без транспиляции).
 */
export async function syntheticMic(ctx: BrowserContext, level = 0.3) {
  const content = `(() => {
    const st = (window.__qaMic = { level: ${level}, requests: 0, cardShown: 0, cardOn: false });
    const md = navigator.mediaDevices;
    if (!md || !md.getUserMedia) return;
    const real = md.getUserMedia.bind(md);
    let ac = null, gain = null, osc = null;
    window.__qaMicSet = (v) => { st.level = v; if (gain) gain.gain.value = v; };
    md.getUserMedia = async (c) => {
      if (!c || !c.audio) return real(c);
      st.requests++;
      if (!ac) {
        ac = new AudioContext();
        gain = ac.createGain();
        gain.gain.value = st.level;
        osc = ac.createOscillator();
        osc.frequency.value = 220;
        osc.connect(gain);
        osc.start();
      }
      if (ac.state === 'suspended') { try { await ac.resume(); } catch (e) {} }
      const dest = ac.createMediaStreamDestination();
      gain.connect(dest);
      return dest.stream;
    };
    new MutationObserver(() => {
      const on = (document.body && document.body.innerText || '').includes('${MIC.cardTitle}');
      if (on && !st.cardOn) st.cardShown++;
      st.cardOn = on;
    }).observe(document, { childList: true, subtree: true, characterData: true });
  })();`;
  await ctx.addInitScript({ content });
}

export const setMic = (page: Page, level: number) => page.evaluate((v) => (window as unknown as { __qaMicSet: (x: number) => void }).__qaMicSet(v), level);
export const micStats = (page: Page) =>
  page.evaluate(() => (window as unknown as { __qaMic: { level: number; requests: number; cardShown: number; cardOn: boolean } }).__qaMic);

/** Подмена end-candidate-attempt: считает вызовы, запоминает тела, отдаёт заданный статус попытки. */
export async function mockEnd(page: Page, status: 'completed' | 'technical_failure') {
  const calls: { body: string }[] = [];
  await page.route('**/functions/v1/end-candidate-attempt', (route: Route) => {
    const req = route.request();
    const h = req.headers();
    const cors = {
      'access-control-allow-origin': h['origin'] || '*',
      'access-control-allow-headers': h['access-control-request-headers'] || '*',
      'access-control-allow-methods': 'GET, POST, PUT, OPTIONS',
    };
    if (req.method() === 'OPTIONS') return route.fulfill({ status: 200, headers: cors, body: 'ok' });
    calls.push({ body: req.postData() || '' });
    return route.fulfill({
      status: 200,
      headers: { ...cors, 'content-type': 'application/json' },
      body: JSON.stringify({ attempt: { status, end_reason: status === 'completed' ? 'candidate_ended' : 'technical_failure' }, recording: null }),
    });
  });
  return calls;
}

/** Карточка потери микрофона + статус (ожидание без фиксированных пауз). */
export async function expectMicLossShown(page: Page, timeout: number) {
  await expect(page.getByText(MIC.cardTitle, { exact: true })).toBeVisible({ timeout });
  await expect(page.getByRole('status').filter({ hasText: MIC.status })).toBeVisible();
  await expect(page.getByText(MIC.cardBody)).toBeVisible();
  await expect(page.getByText(MIC.cardTimeout)).toBeVisible();
  await expect(page.getByRole('button', { name: MIC.retry })).toBeVisible();
}
